"""Four sprint journeys: guided cells, integrated practice and a checkpoint."""
import json
import re
import nbformat as n


def pair(title, text, code, anchor):
    md=n.v4.new_markdown_cell('## '+title+'\n\n'+text);md.id=anchor;md.metadata['id']=anchor
    cell=n.v4.new_code_cell(code);cell.id=anchor+'-code';cell.metadata['id']=cell.id
    return [md,cell]


def enrich(module, pin, setup, sprint=None):
    paths=json.loads((module/'maintainer/learning-path.json').read_text())
    for notebook in sorted((module/'notebooks').glob('0[1-4]-*.ipynb')):
        if sprint and not notebook.name.startswith(f'{sprint:02}-'):continue
        if notebook.name.startswith('01'):continue
        nb=n.read(notebook,as_version=4)
        matching=[x for x in paths if x['notebook']==notebook.name]
        links='\n'.join('- ['+x['title']+'](https://github.com/richhiey/ml-llm-ops/blob/main/module-a/'+x['public_path']+')' for x in matching)
        nb.cells[0].source += '\n\nUse this one notebook throughout the sprint: predict → run the guided cells → add your answers in **Your turn** → finish the checkpoint. Campus notes explain the same work; you do not repeat it in a second notebook.\n\n<details><summary>Campus notes for this sprint</summary>\n\n'+links+'\n\n</details>'
        nb.cells[1].metadata['tags']=['setup'];nb.cells[1].id='setup';nb.cells[1].metadata['id']='setup'
        if notebook.name.startswith('02'):
            nb.cells[2:2]=pair('Calculate the metric distinction','Illustrative errors A=[2,2,8] and B=[4,4,4] have the same average absolute error. Predict which has larger RMSE and why before calculating. These are teaching values, not experimental scores.',"import numpy as np\nfor label, errors in [('A',[2,2,8]),('B',[4,4,4])]:\n    errors=np.asarray(errors,dtype=float)\n    print(label,'MAE',np.abs(errors).mean(),'RMSE',np.sqrt((errors**2).mean()))",'metric-reasoning')
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Run the declared matrix' in c.source)
            nb.cells[index].id='tracking-records';nb.cells[index].metadata['id']='tracking-records'
            plan=n.v4.new_markdown_cell('## Plan before running\n\nRecord five positive `alpha` values, including `1` as the anchor. Hold the snapshot, split, feature order, scaling, solver and guard fixed. State the primary validation metric and its direction, then label one hypothetical changed-partition comparison as excluded. You may use the supplied five values; complete this plan before running the next cell. Keep the final holdout closed.')
            plan.id='experiment-plan';plan.metadata['id']=plan.id
            nb.cells.insert(index,plan)
            index+=1
            nb.cells[index].source+='\n\nThe public `run_matrix` fixture supplies five alpha values; your independent matrix may choose another declared set. Keep the returned IDs: the store can contain other successful executions. Parameters and metrics are not the fitted artifact; the model URI and recovery files carry the next links.'
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Validate an assistant' in c.source)
            nb.cells[index:index]=pair('Compare logging with the model fixed','Reuse the matrix run with alpha=1 as the autologging example. Run just one matching configuration with logging off. This pair investigates logging while keeping the model and validation rows fixed. Predict whether validation RMSE should change, then compare the recorded key sets.',"off=ws.run(Config(alpha=1,range_guard=True,autolog=False),name='logging-off')\non=next(record for record in records if float(record['config']['alpha'])==1.0)\noff_raw=ws.client.get_run(off['run_id']).data\non_raw=ws.client.get_run(on['run_id']).data\nprint('Added parameters:',sorted(set(on_raw.params)-set(off_raw.params)))\nprint('Added metrics:',sorted(set(on_raw.metrics)-set(off_raw.metrics)))\nassert 'ridge__alpha' in on_raw.params\nassert abs(off['metrics']['rmse_kwh']-on['metrics']['rmse_kwh'])<=1e-6\nassert len(rows)==5",'logging-comparison')
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Validate an assistant' in c.source)
            nb.cells[index].id='assistant-review';nb.cells[index].metadata['id']='assistant-review'
            nb.cells[index].source+='\n\nSplit each actual response into claims: winner/metric, controls and operational recommendations. Check every claim against a source field or name the missing evidence. The code below checks numeric selection only; it does not establish that you directed an assistant or reviewed its prose.'
            nb.cells+=pair('Recover the record behind the recommendation','Inspect a stored manifest and compare it with the raw run. This connects the selected table row to recoverable configuration and model identity.',"recovery=Path(ws.client.download_artifacts(best.run_id,'reproduction/manifest.json'))\nsaved=json.loads(recovery.read_text())\nassert saved['run_id']==best.run_id\nassert saved['metrics']['rmse_kwh']==float(best.rmse_kwh)\nprint(saved['config'],saved['model_uri'])",'manifest-check')
        elif notebook.name.startswith('03'):
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Register and approve' in c.source)
            nb.cells[index:index+2]=pair('Register a pending artifact','A run, logged model and registered version are different identities. Record each returned value. Registration must not silently become approval or active selection.',"ws=Workspace(state/'tracking')\napproved=ws.run(Config(alpha=1,range_guard=True),name='baseline-candidate')\nv1=register(ws,approved['run_id'])\ncandidate=ws.client.get_model_version(MODEL_NAME,v1)\nprint(approved['run_id'],approved['model_uri'],v1,candidate.tags)\nassert candidate.tags['validation_status']=='pending'\nassert candidate.run_id==approved['run_id']",'register-pending')+pair('Observe the pending boundary','Predict what happens if a pending version is selected. The helper applies a teaching policy; storing tags and aliases alone would not enforce this decision.',"try:\n    activate(ws,v1,'Deliberate pending-selection probe')\nexcept ValueError as error:\n    print('Expected rejection:',error)\nelse:\n    raise AssertionError('Pending selection accepted')",'registry-identities')+pair('Validate the observed behavior and select','Check a valid table is preserved and an invalid hour rejects. The approval helper also checks finite held-out RMSE and guard configuration; it does not execute your tests for you. Keep the observed rationale distinct from a magic approval label.',"import pandas as pd\nframe=ingest();pd.testing.assert_frame_equal(validate_ranges(frame),frame)\nbad=frame.copy();bad.loc[0,'hour']=24\ntry:\n    validate_ranges(bad)\nexcept ValueError:\n    print('Observed hour=24 rejection')\nelse:\n    raise AssertionError('Invalid hour accepted')\napprove(ws,v1,'Observed valid-copy/hour24 probes and finite validation RMSE<=5')\nprint(activate(ws,v1,'Validated baseline selected'))",'approve-select')
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Reproduce the approved' in c.source)
            nb.cells[index].id='reproduce-reference';nb.cells[index].metadata['id']='reproduce-reference'
            nb.cells[index].source+='\n\nThe destination does not exist before this call. The original manifest identifies the recipe. `reproduce` checks current source/data/environment before fitting, then compares the same evaluation partition. New execution IDs are expected; a different snapshot is not. This reference is a new-store replay, not a new-environment proof.'
            nb.cells+=pair('Inspect the source bundle before recovery','A hash cannot reconstruct missing bytes. Inspect the archive members and identify the actual source, data and lock needed for a fresh environment. Do not extract over your working project.',"import tarfile\nsource=Path(ws.client.download_artifacts(approved['run_id'],'reproduction/source.tar.gz'))\nwith tarfile.open(source) as archive:\n    members=archive.getnames()\nprint([name for name in members if name in ['pyproject.toml','uv.lock','src/campus_mlops/pipeline.py','src/campus_mlops/data/demand-v1.csv']])\nassert all(name in members for name in ['pyproject.toml','uv.lock','src/campus_mlops/pipeline.py'])",'source-recovery')
        else:
            nb.cells[2].id='connected-handoff';nb.cells[2].metadata['id']='connected-handoff'
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Reproduce before' in c.source)
            nb.cells[index:index]=pair('Inspect one connected identity chain','Predict which identities should agree before reading them. The registered artifact must point to the selected training run, and the new batch must report that source run and version.',"selected=ws.client.get_model_version_by_alias(MODEL_NAME,'active')\nassert selected.run_id==record['run_id']==inference['run_id']\nassert str(selected.version)==str(version)==inference['resolved_version']\nprint('Run → version → batch:',record['run_id'],version,inference['resolved_version'])",'identity-chain')+pair('Keep a failed candidate from changing active','This is an intentionally rejected candidate, not another configuration to promote. Record active before/after; registration can succeed even when approval fails.',"before=str(ws.client.get_model_version_by_alias(MODEL_NAME,'active').version)\nrejected=ws.run(Config(alpha=100,range_guard=True),name='rejected-candidate')\nrejected_version=register(ws,rejected['run_id'])\ntry:\n    approve(ws,rejected_version,'Deliberate failing gate probe')\nexcept ValueError as error:\n    print('Expected rejection:',error)\nelse:\n    raise AssertionError('Invalid approval accepted')\nafter=str(ws.client.get_model_version_by_alias(MODEL_NAME,'active').version)\nassert before==after",'failed-gate')
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Evaluate the reserved' in c.source)
            nb.cells[index].source+='\n\nConfiguration selection is already complete in this reference. Report this result separately; do not retune alpha against it or insert it into the validation comparison. The approval policy is validation-based, so final-partition observations cannot be promoted through that gate.'
            nb.cells+=pair('Inspect what the receiver must recover','The notebook replay above used the same environment. A stronger handoff restores the source archive to a new folder, creates a new locked environment and uses a new state. The following inspects real recovery content; follow the full Campus handoff activity for the independent receiving run.',"source=Path(ws.client.download_artifacts(record['run_id'],'reproduction/source.tar.gz'))\nprint('Recoverable source bytes:',source.stat().st_size)\nprint('Recorded command:',record['command'])\nprint('Tolerance:',report['tolerance'],'delta:',report['rmse_delta'])\nassert source.is_file() and report['lineage_matched']",'handoff-recovery')
        for i,c in enumerate(nb.cells):
            if 'id' not in c.metadata:
                slug='cell-'+str(i);c.id=slug;c.metadata['id']=slug
        add_practice(nb, int(notebook.name[:2]), module)
        n.write(nb,notebook)


def add_practice(nb, sprint, module):
    def note(title, text, anchor):
        cell=n.v4.new_markdown_cell('## '+title+'\n\n'+text)
        cell.id=anchor; cell.metadata['id']=anchor; nb.cells.append(cell)
    if sprint==2:
        note('Your turn: plan, compare and review',
            'Use the matrix plan you wrote before execution. If you choose different values, replace the fixture call with five `ws.run(Config(...))` calls and rank your results. Then: (1) inspect those IDs in the local MLflow UI; (2) reuse the logging-on/off pair to explain which keys autologging adds; (3) obtain an actual approved-assistant response and audit its claims against your table. Reuse these outputs throughout the sprint. The supplied fixture is one valid plan; your chosen values may have a different winner.', 'experiment-work')
        checkpoint='Harbor needs a justified selection from five controlled runs. Reuse your matrix, UI comparison, logging pair and assistant claim table. Include an actually observed training metric as an excluded observation, keeping it out of validation ranking. Explain comparability, the selected run ID and any unsupported assistant recommendation. Keep the final holdout closed. Complete the Campus client brief in this notebook.'
    elif sprint==3:
        note('Your turn: recover a run and handle an incident',
            'Use the run and manifests produced above for the past-run activity, retaining the original identity before replay. For independent rollback, prepare an incident with `prepare_case("rollback", state/"your-incident")`, then read its `case.json` and open `Workspace(state/"your-incident")`. This fixture leaves the trial active; you choose the response. Apply the revised 1.6-kWh client limit, inspect approval/source metrics, restore a suitable prior version and prove a new batch used it. Keep before/after selection and a reasoned audit note here. A new store replay proves state independence; fresh-environment recovery comes during handoff.', 'registry-work')
        checkpoint='Prepare the distinct Harbor incident with `prepare_case("registry-assessment", state/"harbor")`, read `case.json`, and inspect `Workspace(state/"harbor")`. The client limit is 1.45 kWh and the newest version is pending. Identify a qualifying prior approved version, restore it, tag the incident, run a new batch and reproduce its source run. Complete the Campus client brief without copying the worked rollback decision.'
    else:
        note('Your turn: hand over one working project',
            'Continue with your actual edited project and selected configuration. Make a short inventory: what works, what is missing, and which missing item blocks the receiver. Adapt the demonstrated chain to that project using `project_python`/`course_cli` (fresh processes), rather than importing edited source over the reference kernel. Retain a failed approval with active unchanged. Check batch row order, finite outputs, resolved version and whole-job time; run invalid input separately. Write the exact setup/run instructions alongside the source. Follow [fresh-environment recovery](https://github.com/richhiey/ml-llm-ops/blob/main/module-a/docs/clean-state.md) locally: recover source to a new folder, create its locked environment and use a new store. Compare lineage and RMSE within 1e-6 kWh. Use one project and one handoff index for all these activities.', 'handoff-work')
        checkpoint='Hand Harbor your working project, setup/run instructions and compact handoff index. A receiver must recover source/data/configuration/environment, build a new locked environment, rerun in a new store, reproduce within 1e-6 kWh and produce the required 24-row batch within 60 seconds. Apply the Campus final acceptance brief, retaining any failure and its fix. The reference replay above shares a kernel and does not replace this independent receiving run. An optional T4 model transfer stays within the same contracts and project.'
    note('Sprint checkpoint',checkpoint,'checkpoint-work')
    note('Finish and keep your work',
         'Save this notebook and the linked project/output files. Keep one sprint submission, reusing the work already completed. Temporary tracking directories disappear when the environment is discarded; save the files before closing it. Continue with the same project in the next sprint.', 'finish')
